public class JISBookTable extends common
{
    /// <summary>
    /// Determines if concurrent deletes should throw exception.
    /// </summary>
    /// <returns>true, if exception should be thrown; otherwise, false.</returns>
    public boolean shouldThrowExceptionOnZeroDelete()
    {
        return true;
    }

    public static boolean exist(JISId _id)
    {
        return (select firstonly RecId from JISBookTable
            where JISBookTable.Id == _id).RecId != 0;
    }

    public static JISBookTable find(JISId _id)
    {
        JISBookTable bookTable;

        select firstonly bookTable
            where bookTable.Id == _id;

        return bookTable;
    }

    public static JISBookTable findRecId(RecId _recId)
    {
        JISBookTable bookTable;

        select firstonly bookTable
            where bookTable.RecId == _recId;

        return bookTable;
    }

    public static int selectCountByGenre(JISGenreEnum _genre)
    {
        JISBookTable bookTable;

        select count(RecId) from bookTable
            group by Genre
            where bookTable.Genre == _genre;

        return bookTable.RecId;
    }

    [SysClientCacheDataMethod(true)]
    public display JISAuthorFullName dispAuthorFullName()

        JISAuthorTable authorTable = JISAuthorTable::findRecId(this.Author);

        return authorTable.FirstName + ' ' + authorTable.LastName;
    }

    [SysClientCacheDataMethod(true)]
    public display JISInventoryQty dispCurrentInventory()
    {
        return this.currentInventory();
    }

    public Qty currentInventory(RecId _excludeTransactionRecId = 0)
    {
        JISBookInventoryTransaction transactions;

        select sum(Qty) from transactions
            where transactions.Book == this.RecId
            && transactions.RecId != _excludeTransactionRecId;

        return transactions.Qty;
    }

    public Common AuthorTableLookup(FormReferenceControl _formReferenceControl)
    {
        SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(JISAuthorTable), _formReferenceControl);

        refTableLookup.parmQuery(this.getLookupQuery());
        refTableLookup.addLookupfield(fieldNum(JISAuthorTable, Id));
        refTableLookup.addLookupfield(fieldNum(JISAuthorTable, FirstName));
        refTableLookup.addLookupfield(fieldNum(JISAuthorTable, LastName));
        refTableLookup.addLookupfield(fieldNum(JISAuthorTable, IsDead));

        return refTableLookup.performFormLookup();
    }

    private Query getLookupQuery()
    {
        Query               q = new Query();
        QuerybuildDataSource qbds = q.addDataSource(tableNum(JISAuthorTable));

        qbds.addRange(fieldNum(JISAuthorTable, IsDead)).value(queryValue(NoYes::No));

        return q;
    }

}
